import React from "react";
import { useCurrentFrame } from "remotion";
import { ChipFacilScenes } from "./ChipFacil";
import MAPA from "./mapa-v2.json";

// v2 (06/11): "tire as pausas da narração". Voz src/voz-v2.wav = voz-v1 com cada pausa de 0,2 s ou mais reduzida a 0,15 s.
// As cenas são as da v1; uma tabela converte o tempo novo no antigo (mapa-v2.json: [início novo, início antigo, duração]).
// Em cada corte o salto é distribuído nos 0,45 s antes dele (a transição corre mais rápido), e a fala seguinte fica em sincronia.
export const CF2_FPS = 30;
const LEAD = 0.25;
export const CF2_FRAMES = Math.round(29.4 * CF2_FPS);
const M = MAPA as [number, number, number][];
const W1 = 0.45, W2 = 0.075;

export const novoParaAntigo = (t: number) => {
  for (let i = 1; i < M.length; i++) {
    const b = M[i][0];
    if (t >= b - W1 && t < b + W2) {
      const e = M[i - 1][1] + M[i - 1][2]; // fim do trecho anterior (tempo antigo)
      const J = M[i][1] - e;
      return e - W1 + (t - (b - W1)) * (W1 + W2 + J) / (W1 + W2);
    }
  }
  let seg = M[0];
  for (const s of M) if (t >= s[0]) seg = s;
  return seg[1] + (t - seg[0]);
};

export const ChipFacilV2: React.FC = () => {
  const frame = useCurrentFrame();
  return <ChipFacilScenes t={novoParaAntigo(frame / CF2_FPS - LEAD)} />;
};

import { loadFont } from "@remotion/google-fonts/Manrope";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// CHIP FÁCIL (cliente chip-facil). Motion: vieram só 2 imagens (mascote e o símbolo CF), mais o site chipfacil.com.br.
// Identidade das imagens: roxo profundo, magenta do "C" (#F51BEA), "F" branco em pincel, mascote de boné roxo.
// Do site: fundo preto, letra sem serifa pesada, "Seu número. Fácil de lembrar.", (00) 00000-0000 como exemplo.
// Tom: moderno e descontraído, mas de empresa (vende para empresas, advogados, médicos): molas sem passar do ponto,
// câmera em aproximação reta, nada balançando.
// Fio: o número (discador do problema → dígitos → DDD → endereço do site).
// Problema (cliente que esquece o número) em desenho genérico; marca e mascote só entram em "Com a Chip Fácil".
// Tempos = tempos da locução src/voz-v1.mp3 (t = 0 no começo da voz; o vídeo tem LEAD de entrada).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "700", "800"], subsets: ["latin", "latin-ext"] });

export const CF_FPS = 30;
const LEAD = 0.25;
export const CF_FRAMES = Math.round(34.5 * CF_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const SOFT = Easing.out(Easing.back(0.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: SOFT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const f2 = (x: number) => x.toFixed(2);

const BG = "#120619";
const VIO = "#5B17B0";
const VIO2 = "#7A22D6";
const MAG = "#F51BEA";
const MAGL = "#FF8AF7";
const LIGHT = "#F7F1FD";
const INK = "#200836";
const WHITE = "#FFFFFF";
const PILL = `linear-gradient(90deg, ${MAG} 0%, #B41EE6 100%)`;

// Trocas de cena (tempo da voz)
const T2 = 3.45, T3 = 7.98, T4 = 13.3, T5 = 18.2, T6 = 22.02, T7 = 25.0, T8 = 29.05;

// ───────── texto pela máscara: cada palavra nasce de baixo de uma linha invisível e fica parada ─────────
type W = { w: string; at: number; hl?: boolean };
const Title: React.FC<{ t: number; lines: W[][]; size: number; top: number; color?: string; out?: number; pill?: string; pillText?: string; gap?: number }> = ({ t, lines, size, top, color = WHITE, out, pill = PILL, pillText = WHITE, gap = 0.1 }) => {
  const first = lines[0][0].at;
  if (t < first - 0.05) return null;
  const o = out === undefined ? 0 : lin(t, out, out + 0.14);
  if (o >= 1) return null;
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * gap, opacity: 1 - o, filter: o > 0 ? `blur(${f2(o * 10)}px)` : undefined }}>
      {lines.map((ln, i) => (
        <div key={i} style={{ display: "flex", gap: size * 0.26, justifyContent: "center" }}>
          {ln.map(({ w, at, hl }, j) => {
            const e = k(t, at, 0.5);
            return (
              <div key={j} style={{ overflow: "hidden", padding: `0 ${size * 0.04}px ${size * 0.06}px`, ...(hl ? { transform: `scale(${(0.92 + 0.08 * pop(t, at, 0.5)).toFixed(4)})` } : {}) }}>
                <div style={{ fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: hl ? pillText : color, transform: `translateY(${f2((1 - e) * 115)}%)`, ...(hl ? { background: pill, padding: `${size * 0.02}px ${size * 0.24}px ${size * 0.08}px`, borderRadius: size * 0.26 } : {}) }}>
                  {w}
                </div>
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
};

// Câmera: impulso na entrada da cena + aproximação reta e lenta (sem balanço)
const Cam: React.FC<{ t: number; a: number; b: number; s0?: number; s1?: number; kick?: number; ox?: number; oy?: number; dy?: number; children: React.ReactNode }> = ({ t, a, b, s0 = 1, s1 = 1.05, kick = 0.08, ox = 50, oy = 50, dy = 0, children }) => {
  const p = lin(t, a, b + 0.5);
  const imp = (1 - k(t, a, 0.7)) * kick;
  return <AbsoluteFill style={{ transformOrigin: `${ox}% ${oy}%`, transform: `scale(${(s0 + (s1 - s0) * p + imp).toFixed(4)})` }}><AbsoluteFill style={{ transform: `translateY(${dy}px)` }}>{children}</AbsoluteFill></AbsoluteFill>;
};
const Glow: React.FC<{ y?: number; a?: number; c?: string }> = ({ y = 50, a = 0.28, c = "122,34,214" }) => (
  <AbsoluteFill style={{ background: `radial-gradient(circle at 50% ${y}%, rgba(${c},${a}) 0%, rgba(${c},0) 58%)` }} />
);

// ───────── ícones (traço) ─────────
type Ico = React.FC<{ s: number; c: string; w?: number }>;
const sv = (s: number, c: string, w: number, ch: React.ReactNode) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoBuilding: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><rect x="5" y="3.5" width="14" height="17" rx="1.4" /><path d="M9 7.5h1.5M13.5 7.5H15M9 11h1.5M13.5 11H15M9 14.5h1.5M13.5 14.5H15M10.5 20.5v-3h3v3" /></>);
const IcoScale: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><path d="M12 4v16M8 20h8M5 7h14" /><path d="M5 7l-2.6 5.5a2.6 2.6 0 005.2 0zM19 7l-2.6 5.5a2.6 2.6 0 005.2 0z" /></>);
const IcoSteth: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><path d="M6 3.5v5a4.5 4.5 0 009 0v-5" /><path d="M10.5 13v2.5a4 4 0 008 0V13" /><circle cx="18.5" cy="11" r="2" /></>);
const IcoClinic: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><rect x="3.5" y="3.5" width="17" height="17" rx="4" /><path d="M12 8v8M8 12h8" /></>);
const IcoStore: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><path d="M3.5 9.5L5 4h14l1.5 5.5" /><path d="M3.5 9.5a2.8 2.8 0 005.67 0 2.8 2.8 0 005.66 0 2.8 2.8 0 005.67 0" /><path d="M5 12v8h14v-8M10 20v-4.5h4V20" /></>);
const IcoTalk: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><path d="M4 5.5h16v10H10l-4.5 3.5v-3.5H4z" /><path d="M8 10.5h.1M12 10.5h.1M16 10.5h.1" /></>);
const IcoMega: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><path d="M4 10v4h3l7 4.5v-13L7 10z" /><path d="M17.5 9.5a3.5 3.5 0 010 5M7 14l1.2 5h2.3l-1-5" /></>);
const IcoBulb: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><path d="M9 17.5h6M10 20.5h4" /><path d="M12 3.5a6 6 0 00-3.6 10.8c.4.3.6.8.6 1.3v1.9h6v-1.9c0-.5.2-1 .6-1.3A6 6 0 0012 3.5z" /></>);
const IcoGlobe: Ico = ({ s, c, w = 1.7 }) => sv(s, c, w, <><circle cx="12" cy="12" r="8.5" /><path d="M3.5 12h17M12 3.5c2.4 2.4 3.4 5.2 3.4 8.5s-1 6.1-3.4 8.5c-2.4-2.4-3.4-5.2-3.4-8.5s1-6.1 3.4-8.5z" /></>);

// O símbolo CF recortado da arte do cliente (src/logo-simbolo.png, 760×600)
const Logo: React.FC<{ w: number; c?: number; f?: number }> = ({ w, c = 1, f = 1 }) => {
  const h = (w * 600) / 760;
  const cut = 0.44; // onde o "C" acaba e o "F" começa, na largura
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      {/* C: abre girando (máscara em leque) */}
      <div style={{ position: "absolute", inset: 0, clipPath: `inset(0 ${f2((1 - cut) * 100)}% 0 0)`, WebkitMaskImage: `conic-gradient(from 20deg at 25% 50%, #000 ${f2(c * 360)}deg, transparent ${f2(c * 360 + 0.5)}deg)` }}>
        <Img src={staticFile("chip-facil/logo-simbolo.png")} style={{ width: w, height: h }} />
      </div>
      {/* F: pinceladas entram da esquerda para a direita */}
      <div style={{ position: "absolute", inset: 0, clipPath: `inset(-2% ${f2((1 - f) * (1 - cut) * 100)}% -2% ${f2(cut * 100)}%)` }}>
        <Img src={staticFile("chip-facil/logo-simbolo.png")} style={{ width: w, height: h }} />
      </div>
    </div>
  );
};
const Wordmark: React.FC<{ size: number; t: number; at: number }> = ({ size, t, at }) => {
  const e = k(t, at, 0.55);
  return (
    <div style={{ overflow: "hidden", padding: `0 ${size * 0.06}px ${size * 0.06}px` }}>
      <div style={{ fontFamily: F, fontWeight: 800, fontSize: size, letterSpacing: "-0.04em", lineHeight: 1.1, whiteSpace: "nowrap", color: WHITE, transform: `translateY(${f2((1 - e) * 115)}%)` }}>
        Chip <span style={{ color: MAGL }}>Fácil</span>
      </div>
    </div>
  );
};

// ───────── cena 1 · o problema: o cliente começa a discar e esquece o número ─────────
const DIGITS = ["9", "7", "4", "3", "?", "?"];
const KEYS = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "*", "0", "#"];
const S1: React.FC<{ t: number }> = ({ t }) => {
  const phoneIn = k(t, -0.25, 0.8);
  const typeAt = (i: number) => 0.35 + i * 0.2;
  const forget = k(t, 2.42, 0.6);
  const q = pop(t, 2.55, 0.5);
  const pressed = (key: string) => DIGITS.slice(0, 4).some((d, i) => d === key && t >= typeAt(i) && t < typeAt(i) + 0.22);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Glow y={62} a={0.22} />
      <Cam t={t} a={-0.25} b={T2} s0={1} s1={1.05} kick={0.14} oy={60}>
        <Title t={t} size={96} top={250} out={2.05} lines={[[{ w: "Seu", at: 0 }, { w: "cliente", at: 0.24 }], [{ w: "quis", at: 0.54 }, { w: "te", at: 0.76 }, { w: "ligar...", at: 0.84 }]]} />
        <Title t={t} size={96} top={250} lines={[[{ w: "mas", at: 2.2 }, { w: "não", at: 2.42 }, { w: "lembrou", at: 2.54 }], [{ w: "o seu número.", at: 2.84, hl: true }]]} />
        <div style={{ position: "absolute", left: 300, top: 600, width: 480, height: 880, borderRadius: 72, border: "6px solid rgba(255,255,255,0.88)", background: "rgba(255,255,255,0.03)", transform: `translateY(${f2((1 - phoneIn) * 520)}px)`, opacity: phoneIn }}>
          <div style={{ position: "absolute", left: 180, top: 22, width: 108, height: 22, borderRadius: 11, background: "rgba(255,255,255,0.88)" }} />
          {/* visor do discador */}
          <div style={{ position: "absolute", left: 0, right: 0, top: 92, height: 120, display: "flex", justifyContent: "center", alignItems: "center", gap: 10 }}>
            {DIGITS.map((d, i) => {
              const e = pop(t, typeAt(i), 0.25);
              if (t < typeAt(i)) return null;
              const dx = (i - 2.5) * 40 * forget;
              const isQ = d === "?";
              return (
                <div key={i} style={{ fontFamily: F, fontWeight: 700, fontSize: 70, color: isQ ? MAGL : WHITE, transform: `translate(${f2(dx)}px, ${f2(forget * (60 + i * 25))}px) scale(${f2(0.6 + 0.4 * e)})`, opacity: e * (1 - forget), filter: forget > 0 ? `blur(${f2(forget * 14)}px)` : undefined }}>
                  {d}
                </div>
              );
            })}
          </div>
          {/* interrogação no lugar do número */}
          {t > 2.5 ? (
            <div style={{ position: "absolute", left: 0, right: 0, top: 70, display: "flex", justifyContent: "center" }}>
              <div style={{ width: 150, height: 150, borderRadius: 75, background: PILL, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 104, color: WHITE, transform: `scale(${f2(q)})` }}>?</div>
            </div>
          ) : null}
          {/* teclado */}
          <div style={{ position: "absolute", left: 60, top: 250, width: 360, display: "grid", gridTemplateColumns: "repeat(3, 1fr)", rowGap: 22, justifyItems: "center" }}>
            {KEYS.map((key, i) => {
              const on = pressed(key);
              const e = k(t, -0.1 + i * 0.03, 0.4);
              return (
                <div key={key} style={{ width: 96, height: 96, borderRadius: 48, border: "3px solid rgba(255,255,255,0.28)", background: on ? MAG : "transparent", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 700, fontSize: 40, color: WHITE, opacity: e * (1 - 0.45 * forget), transform: `scale(${f2(0.7 + 0.3 * e)})` }}>
                  {key}
                </div>
              );
            })}
          </div>
          <div style={{ position: "absolute", left: 186, top: 742, width: 108, height: 108, borderRadius: 54, background: MAG, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${f2(k(t, 0.1, 0.5))})` }}>
            <svg width={52} height={52} viewBox="0 0 24 24" fill={WHITE}><path d="M6.6 10.8a15.1 15.1 0 006.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.1.4 2.3.6 3.6.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1A17 17 0 013 4c0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.6.1.3 0 .7-.2 1z" /></svg>
          </div>
        </div>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · a solução: marca, mascote e "fácil de lembrar" ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const up = io(t, 4.75, 5.2); // logo sobe para dar lugar ao mascote
  const card = k(t, 5.12, 0.7);
  const logoW = 400 - 210 * up;
  const logoTop = 560 - 360 * up;
  return (
    <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 45%, ${VIO2} 0%, ${VIO} 45%, #3A0E78 100%)` }}>
      <Cam t={t} a={T2} b={T3} s0={1.04} s1={1} kick={0.06} dy={150}>
        <div style={{ position: "absolute", left: 0, right: 0, top: logoTop, display: "flex", flexDirection: "column", alignItems: "center", gap: 18 - 10 * up }}>
          <div style={{ transform: `scale(${f2(0.85 + 0.15 * k(t, 3.6, 0.6))})` }}>
            <Logo w={logoW} c={io(t, 3.6, 4.2)} f={k(t, 4.25, 0.5)} />
          </div>
          <div style={{ transform: `scale(${f2(1 - 0.45 * up)})`, transformOrigin: "50% 0%" }}>
            <Wordmark size={120} t={t} at={4.3} />
          </div>
        </div>
        {t > 5.1 ? (
          <div style={{ position: "absolute", left: 250, top: 470, width: 580, height: 580, borderRadius: 56, overflow: "hidden", boxShadow: "0 40px 90px rgba(20,4,40,0.45)", transform: `translateY(${f2((1 - card) * 260)}px) scale(${f2(0.8 + 0.2 * card)})`, opacity: card }}>
            <Img src={staticFile("chip-facil/mascote.jpg")} style={{ width: 580, height: 580, objectFit: "cover", transform: `scale(${f2(1.12 - 0.08 * lin(t, 5.0, 8.0))})` }} />
          </div>
        ) : null}
        <Title t={t} size={92} top={1110} lines={[[{ w: "Um", at: 5.88 }, { w: "número", at: 5.98 }], [{ w: "fácil de lembrar", at: 6.7, hl: true }]]} pill={WHITE} pillText={VIO} />
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · os números: repetidos, sequências, sem anotar ─────────
const Reel: React.FC<{ t: number; seq: { at: number; d: number }[]; i: number }> = ({ t, seq, i }) => {
  // rolo de um dígito: gira passando pelos números até assentar no alvo
  let pos = 0;
  for (const s of seq) {
    const e = k(t, s.at + i * 0.07, 0.55);
    if (t >= s.at + i * 0.07) pos = s.d + 10 * (1 - e) * (1 + i * 0.3);
  }
  const H = 220;
  return (
    <div style={{ width: 168, height: H, borderRadius: 30, background: "rgba(122,34,214,0.22)", border: "3px solid rgba(255,138,247,0.35)", overflow: "hidden", position: "relative" }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: 0, transform: `translateY(${f2(-((pos % 10) + 10) * H)}px)` }}>
        {Array.from({ length: 30 }).map((_, n) => (
          <div key={n} style={{ height: H, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 170, color: WHITE, lineHeight: 1, fontVariantNumeric: "tabular-nums" }}>{n % 10}</div>
        ))}
      </div>
    </div>
  );
};
const S3: React.FC<{ t: number }> = ({ t }) => {
  const tilesOut = io(t, 10.95, 11.2);
  const note = k(t, 11.1, 0.55);
  const strike = io(t, 12.75, 13.15);
  const capA = k(t, 8.75, 0.5) * (1 - lin(t, 9.45, 9.58));
  const capB = k(t, 9.95, 0.5);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Glow y={52} a={0.26} />
      <Cam t={t} a={T3} b={T4} s0={1} s1={1.05} kick={0.07} oy={55} dy={130}>
        <Title t={t} size={104} top={470} out={9.42} lines={[[{ w: "Números", at: 8.38 }], [{ w: "repetidos", at: 8.72, hl: true }]]} />
        <Title t={t} size={104} top={470} out={10.9} lines={[[{ w: "Sequências", at: 9.6 }], [{ w: "marcantes", at: 10.02, hl: true }]]} />
        <Title t={t} size={92} top={470} lines={[[{ w: "Ninguém", at: 11.98 }, { w: "precisa", at: 12.3 }], [{ w: "anotar", at: 12.82, hl: true }]]} />
        {/* antes de "ninguém precisa anotar", a palavra "combinações" ocupa o lugar do título */}
        <Title t={t} size={104} top={530} out={11.9} lines={[[{ w: "Combinações", at: 11.04 }]]} />
        {tilesOut < 1 ? (
          <div style={{ position: "absolute", left: 0, right: 0, top: 820, display: "flex", flexDirection: "column", alignItems: "center", gap: 34, opacity: 1 - tilesOut, transform: `scale(${f2(1 - 0.12 * tilesOut)})`, filter: tilesOut > 0 ? `blur(${f2(tilesOut * 12)}px)` : undefined }}>
            <div style={{ display: "flex", gap: 22, transform: `scale(${f2(0.7 + 0.3 * k(t, 8.3, 0.5))})`, opacity: k(t, 8.3, 0.3) }}>
              {[0, 1, 2, 3].map((i) => (
                <Reel key={i} t={t} i={i} seq={[{ at: 8.38, d: 8 }, { at: 9.6, d: i + 1 }]} />
              ))}
            </div>
            <div style={{ position: "relative", height: 80, width: 840 }}>
              <div style={{ position: "absolute", inset: 0, display: "flex", justifyContent: "center", alignItems: "center", fontFamily: F, fontWeight: 700, fontSize: 58, color: MAGL, opacity: capA, letterSpacing: "0.01em" }}>(00) 00000-0000</div>
              <div style={{ position: "absolute", inset: 0, display: "flex", justifyContent: "center", alignItems: "center", fontFamily: F, fontWeight: 700, fontSize: 58, color: MAGL, opacity: capB }}>simples de guardar</div>
            </div>
          </div>
        ) : null}
        {t > 11.05 ? (
          <div style={{ position: "absolute", left: 220, top: 800, width: 640, height: 440, borderRadius: 36, background: WHITE, boxShadow: "0 40px 90px rgba(0,0,0,0.4)", transform: `translateY(${f2((1 - note) * 300)}px)`, opacity: note, overflow: "hidden" }}>
            {[0, 1, 2, 3].map((r) => (
