// ───────── montagem: cada cena nasce da anterior ─────────
const circle = (t: number, a: number, x: number, y: number, d = 0.45) => `circle(${f2(io(t, a, a + d) * 160)}% at ${x}px ${y}px)`;
export const ChipFacilScenes: React.FC<{ t: number }> = ({ t }) => {
  // 3→4: o bilhete branco cresce e vira o fundo claro
  const m = io(t, T4, T4 + 0.42);
  const ins = `inset(${f2(925 * (1 - m))}px ${f2(204 * (1 - m))}px ${f2(535 * (1 - m))}px ${f2(204 * (1 - m))}px round ${f2(36 * (1 - m))}px)`;
  // 4→5: duas metades se abrem
  const sp = io(t, T5, T5 + 0.4);
  // 6→7: cortina subindo
  const cu = io(t, T7, T7 + 0.42);
  // 2→3: faixa inclinada
  const d = io(t, T3, T3 + 0.38);
  const band = `polygon(${f2(-60 + 260 * d)}% 0%, 200% 0%, 200% 100%, ${f2(-160 + 260 * d)}% 100%)`;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {t < T2 + 0.5 ? <S1 t={t} /> : null}
      {t >= T2 && t < T3 + 0.4 ? <AbsoluteFill style={{ clipPath: t < T2 + 0.46 ? circle(t, T2, 540, 1452) : undefined }}><S2 t={t} /></AbsoluteFill> : null}
      {t >= T3 && t < T4 + 0.45 ? <AbsoluteFill style={{ clipPath: t < T3 + 0.38 ? band : undefined }}><S3 t={t} /></AbsoluteFill> : null}
      {t >= T5 && t < T6 + 0.5 ? <S5 t={t} /> : null}
      {t >= T4 && t < T5 + 0.42 ? (
        t < T5 ? (
          <AbsoluteFill style={{ clipPath: t < T4 + 0.42 ? ins : undefined }}><S4 t={t} /></AbsoluteFill>
        ) : (
          <>
            <AbsoluteFill style={{ clipPath: "inset(0 50% 0 0)", transform: `translateX(${f2(-600 * sp)}px)` }}><S4 t={t} /></AbsoluteFill>
            <AbsoluteFill style={{ clipPath: "inset(0 0 0 50%)", transform: `translateX(${f2(600 * sp)}px)` }}><S4 t={t} /></AbsoluteFill>
          </>
        )
      ) : null}
      {t >= T6 && t < T7 + 0.45 ? <AbsoluteFill style={{ clipPath: t < T6 + 0.46 ? circle(t, T6, 540, 1200) : undefined, transform: `translateY(${f2(-380 * cu)}px)` }}><S6 t={t} /></AbsoluteFill> : null}
      {t >= T7 && t < T8 + 0.5 ? <AbsoluteFill style={{ transform: `translateY(${f2(1920 * (1 - cu))}px)` }}><S7 t={t} /></AbsoluteFill> : null}
      {t >= T8 ? <AbsoluteFill style={{ clipPath: t < T8 + 0.5 ? circle(t, T8, 540, 772, 0.5) : undefined }}><S8 t={t} /></AbsoluteFill> : null}
    </AbsoluteFill>
  );
};

